import 'package:firebase_core/firebase_core.dart';
import 'package:flutter/foundation.dart';
import 'package:recipemate/firebase_options.dart';

/// Initializes Firebase once for the whole application.
///
/// Configuration is read from `firebase_options.dart`, generated by
/// `flutterfire configure`. On Web, Firebase REQUIRES explicit options:
/// calling Firebase.initializeApp() without them always fails in Chrome.
/// If the file is still the empty stub, the app keeps running in degraded
/// mode and [isAvailable] stays false (no invented credentials).
abstract final class FirebaseService {
  static bool isAvailable = false;

  static Future<void> initialize() async {
    try {
      final options = DefaultFirebaseOptions.currentPlatform;
      if (options.apiKey.isEmpty) {
        debugPrint(
          'Firebase non configuré : lance `flutterfire configure` puis '
          'redémarre l’application (sélectionne bien la plateforme web).',
        );
        isAvailable = false;
        return;
      }

      if (Firebase.apps.isEmpty) {
        await Firebase.initializeApp(options: options);
      }

      // Google Sign-In 7 impose un `initialize()` unique : il est désormais
      // centralisé dans AuthService (appelé au premier signIn/signOut) pour
      // éviter la double initialisation qui rendait le comportement indéfini.
      // Sur Web, FirebaseAuth.signInWithPopup() suffit (pas de plugin natif).
      isAvailable = true;
    } on Object catch (error) {
      debugPrint('Initialisation Firebase impossible : $error');
      isAvailable = false;
    }
  }
}
